const Database = require('better-sqlite3');
const path = require('path');
const apiBible = require('./apiBible');
const aiVerse = require('./aiVerse');

const DB_PATH = path.join(__dirname, '../db/bible.db');
let db;

function getDb() {
  if (!db) {
    db = new Database(DB_PATH);
    db.pragma('journal_mode = WAL');
    initSchema();
    // Earlier versions cached verse text generated by an AI model. That is
    // not scripture and must never reach the screen.
    const removed = db.prepare(`DELETE FROM verses WHERE source = 'claude_cache'`).run().changes;
    if (removed) console.log(`[Bible] Removed ${removed} AI-generated verses from the local database`);
  }
  return db;
}

function initSchema() {
  db.exec(`
    CREATE TABLE IF NOT EXISTS verses (
      id          INTEGER PRIMARY KEY AUTOINCREMENT,
      translation TEXT NOT NULL,
      book        TEXT NOT NULL,
      book_num    INTEGER NOT NULL,
      chapter     INTEGER NOT NULL,
      verse       INTEGER NOT NULL,
      text        TEXT NOT NULL,
      source      TEXT DEFAULT 'seed'
    );
    CREATE INDEX IF NOT EXISTS idx_lookup
      ON verses(translation, book_num, chapter, verse);

    CREATE TABLE IF NOT EXISTS bible_structure (
      book_num  INTEGER NOT NULL,
      book      TEXT NOT NULL,
      chapter   INTEGER NOT NULL,
      max_verse INTEGER NOT NULL,
      PRIMARY KEY (book_num, chapter)
    );
  `);
}

// Translations stored in bible.db by `npm run seed` (all public domain)
const LOCAL_TRANSLATIONS = {
  KJV: 'King James Version',
  ASV: 'American Standard Version (1901)',
  YLT: "Young's Literal Translation",
  BBE: 'Bible in Basic English',
};

// Display names for licensed translations served through API.Bible
const LICENSED_NAMES = {
  NKJV: 'New King James Version', AMP: 'Amplified Bible', AMPC: 'Amplified Bible, Classic',
  TPT: 'The Passion Translation', MSG: 'The Message', GNT: 'Good News Translation',
  TLB: 'The Living Bible', NIV: 'New International Version', ESV: 'English Standard Version',
  NLT: 'New Living Translation', NASB: 'New American Standard Bible', CSB: 'Christian Standard Bible',
  CEV: 'Contemporary English Version', NCV: 'New Century Version', HCSB: 'Holman Christian Standard Bible',
  WEB: 'World English Bible', NRSV: 'New Revised Standard Version', RSV: 'Revised Standard Version',
};

function localCounts() {
  const rows = getDb().prepare(`SELECT translation, COUNT(*) AS c FROM verses GROUP BY translation`).all();
  return Object.fromEntries(rows.map(r => [r.translation, r.c]));
}

// What the operator can actually pick: local translations that are seeded,
// plus whatever the API.Bible key unlocks. Everything else is listed as
// unavailable with the reason, never faked.
async function listTranslations() {
  const counts = localCounts();
  const out = [];
  for (const [code, name] of Object.entries(LOCAL_TRANSLATIONS)) {
    out.push({ code, name, provider: 'local', available: (counts[code] || 0) > 30000,
      reason: (counts[code] || 0) > 30000 ? null : 'Not downloaded yet — run npm run seed' });
  }
  const remote = new Set(await apiBible.availableCodes());
  const st = apiBible.status();
  const ai = aiVerse.isAvailable();
  for (const [code, name] of Object.entries(LICENSED_NAMES)) {
    // Licensed text when the API.Bible plan has it, otherwise the AI beta path
    if (remote.has(code)) out.push({ code, name, provider: 'apibible', available: true, reason: null });
    else if (ai) out.push({ code, name, provider: 'ai', available: true, reason: 'AI beta — wording cross-checked, not licensed text' });
    else out.push({ code, name, provider: 'apibible', available: false,
      reason: !st.configured ? 'Needs GEMINI_API_KEY / GROQ_API_KEY (beta) or an API.Bible key' : (st.error || 'Not included in your API.Bible plan') });
  }
  for (const code of remote) {
    if (!LOCAL_TRANSLATIONS[code] && !LICENSED_NAMES[code]) out.push({ code, name: code, provider: 'apibible', available: true, reason: null });
  }
  return out;
}

function localVerse(book, chapter, verse, translation) {
  const row = getDb().prepare(`
    SELECT text, book, chapter, verse, translation, source
    FROM verses
    WHERE book = ? AND chapter = ? AND verse = ? AND translation = ?
  `).get(book, chapter, verse, translation);
  if (!row) return null;
  return {
    reference: `${row.book} ${row.chapter}:${row.verse}`,
    translation: row.translation,
    text: row.text,
    book: row.book,
    chapter: row.chapter,
    verse: row.verse,
    source: row.source || 'local',
    ...(AI_NOTES[row.source] ? { verification: row.source.replace('ai_', ''), note: AI_NOTES[row.source] } : {})
  };
}

const AI_NOTES = {
  ai_verified: 'AI beta · matched by 2+ providers (saved)',
  ai_grounded: 'AI beta · web-searched (saved)',
};

// Confirmed AI answers are saved so the verse is instant and works offline
// next time. Unverified answers are never saved.
function saveAiVerse(v) {
  if (v.verification !== 'verified' && v.verification !== 'grounded') return;
  try {
    const db = getDb();
    db.prepare(`DELETE FROM verses WHERE translation = ? AND book = ? AND chapter = ? AND verse = ?`).run(v.translation, v.book, v.chapter, v.verse);
    db.prepare(`INSERT INTO verses (translation, book, book_num, chapter, verse, text, source) VALUES (?, ?, ?, ?, ?, ?, ?)`)
      .run(v.translation, v.book, getBookNum(v.book), v.chapter, v.verse, v.text, 'ai_' + v.verification);
  } catch (err) {
    console.error('[Bible] Could not save AI verse:', err.message);
  }
}

// ── Get verse — real text only: local DB, then API.Bible, then KJV with the reason ──
async function getVerse(book, chapter, verse, translation = 'KJV') {
  translation = String(translation || 'KJV').toUpperCase();

  const local = localVerse(book, chapter, verse, translation);
  if (local) return local;

  let reason;
  if (LOCAL_TRANSLATIONS[translation]) {
    reason = (localCounts()[translation] || 0) > 30000
      ? `${book} ${chapter}:${verse} is not part of the ${translation} text`
      : `${translation} not downloaded yet — run npm run seed`;
  } else {
    const remote = await apiBible.getVerse(getBookNum(book), book, chapter, verse, translation);
    if (!remote.error) return remote;
    reason = remote.error;

    if (aiVerse.isAvailable()) {
      const kjvRow = localVerse(book, chapter, verse, 'KJV');
      const ai = await aiVerse.getVerse(book, chapter, verse, translation, kjvRow && kjvRow.text);
      if (!ai.error) { saveAiVerse(ai); return ai; }
      reason = ai.error;
    }
  }

  if (translation === 'KJV') return null;
  console.log(`[Bible] ${book} ${chapter}:${verse} (${translation}) unavailable: ${reason} — showing KJV`);
  const kjv = localVerse(book, chapter, verse, 'KJV');
  return kjv && Object.assign(kjv, { requestedTranslation: translation, fallback: true, fallbackReason: reason });
}

// Book number lookup
const BOOK_NUMS = {
  'Genesis':1,'Exodus':2,'Leviticus':3,'Numbers':4,'Deuteronomy':5,
  'Joshua':6,'Judges':7,'Ruth':8,'1 Samuel':9,'2 Samuel':10,
  '1 Kings':11,'2 Kings':12,'1 Chronicles':13,'2 Chronicles':14,
  'Ezra':15,'Nehemiah':16,'Esther':17,'Job':18,'Psalms':19,'Proverbs':20,
  'Ecclesiastes':21,'Song of Solomon':22,'Isaiah':23,'Jeremiah':24,
  'Lamentations':25,'Ezekiel':26,'Daniel':27,'Hosea':28,'Joel':29,
  'Amos':30,'Obadiah':31,'Jonah':32,'Micah':33,'Nahum':34,
  'Habakkuk':35,'Zephaniah':36,'Haggai':37,'Zechariah':38,'Malachi':39,
  'Matthew':40,'Mark':41,'Luke':42,'John':43,'Acts':44,'Romans':45,
  '1 Corinthians':46,'2 Corinthians':47,'Galatians':48,'Ephesians':49,
  'Philippians':50,'Colossians':51,'1 Thessalonians':52,'2 Thessalonians':53,
  '1 Timothy':54,'2 Timothy':55,'Titus':56,'Philemon':57,'Hebrews':58,
  'James':59,'1 Peter':60,'2 Peter':61,'1 John':62,'2 John':63,
  '3 John':64,'Jude':65,'Revelation':66
};

function getBookNum(book) {
  return BOOK_NUMS[book] || null;
}

function searchVerses(query, translation = 'KJV', limit = 10) {
  const db = getDb();
  return db.prepare(`
    SELECT book, chapter, verse, text, translation
    FROM verses
    WHERE translation = ? AND text LIKE ?
    LIMIT ?
  `).all(translation, `%${query}%`, limit);
}

module.exports = { getDb, getVerse, searchVerses, getBookNum, listTranslations };